use open_sdbl::metadata::parse_config_descriptors;
use std::{fs,path::Path,error::Error};
fn run()->Result<(),Box<dyn Error>>{let args=std::env::args().collect::<Vec<_>>();println!("owner_id\tname\tclass_tag\tclass_len\tnative_sections\tsdk_sections\tnative_fields\tsdk_field_membership_total\tknown_field_types\tsection_order_and_names_match\tfield_orders_and_names_match\town_attributes\town_order_matches");for row in fs::read_to_string(&args[1])?.lines(){let c=row.split('\t').collect::<Vec<_>>();assert_eq!(c.len(),8);let ds=parse_config_descriptors(c[0],&fs::read(Path::new(&args[2]).join(c[0]))?)?;let owner=ds.iter().find(|d|d.object_guid.as_str()==c[0]).ok_or("owner missing")?;let parts=c[7].split(';').filter(|s|!s.is_empty()).map(|s|s.split('~').collect::<Vec<_>>()).collect::<Vec<_>>();let section_order=owner.document_tabular_sections.as_ref().is_some_and(|ids|ids.iter().map(|id|id.as_str()).eq(parts.iter().map(|p|p[0])))&&parts.iter().all(|p|ds.iter().filter(|d|d.object_guid.as_str()==p[0]&&d.name==p[1]).count()==1);let mut fields_order=true;let mut membership_total=Some(0usize);let mut known_types=0usize;for p in &parts{let fields=p[2].split(',').filter(|s|!s.is_empty()).map(|s|s.split_once(':').unwrap()).collect::<Vec<_>>();let d=ds.iter().find(|d|d.object_guid.as_str()==p[0]);let ids=d.and_then(|d|d.tabular_section_attributes.as_ref());fields_order&=ids.is_some_and(|ids|ids.iter().map(|id|id.as_str()).eq(fields.iter().map(|(id,_)|*id)))&&fields.iter().all(|(id,name)|ds.iter().filter(|d|d.object_guid.as_str()==*id&&d.name==*name).count()==1);membership_total=membership_total.and_then(|n|ids.map(|ids|n+ids.len()));known_types+=fields.iter().filter(|(id,_)|ds.iter().filter(|d|d.object_guid.as_str()==*id&&d.declared_types.is_some()).count()==1).count();}let own=c[6].split(',').filter(|s|!s.is_empty()).collect::<Vec<_>>();let own_order=owner.document_attributes.as_ref().is_some_and(|ids|ids.iter().map(|id|id.as_str()).eq(own.iter().copied()));println!("{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}",c[0],c[1],c[2],c[3],c[4],owner.document_tabular_sections.as_ref().map_or("None".into(),|ids|ids.len().to_string()),c[5],membership_total.map_or("None".into(),|n|n.to_string()),known_types,section_order,fields_order,owner.document_attributes.as_ref().map_or("None".into(),|ids|ids.len().to_string()),own_order);}Ok(())}
fn main(){if let Err(e)=run(){eprintln!("ERROR:{e}");std::process::exit(1)}}
